// One row per domain and month, flat columns for Sheets.
const s = $('Settings').first().json;
const norm = (d) => String(d || '').trim().toLowerCase().replace(/^https?:\/\//, '').replace(/^www\./, '').replace(/\/$/, '');
const own = norm(s.yourDomain);
const month = new Date().toISOString().slice(0, 7);
const top = (o) => Object.entries(o || {}).slice(0, 3).map(([k, v]) => `${k} ${v}`).join(', ');
return $input.all().map(({ json: r }) => ({ json: {
  month, domain: r.target, yourSite: norm(r.target) === own, found: r.found !== false,
  domainRank: r.domainRank ?? null, backlinks: r.backlinks ?? 0, dofollowBacklinks: r.dofollowBacklinks ?? 0,
  referringDomains: r.referringDomains ?? 0, dofollowReferringDomains: r.dofollowReferringDomains ?? 0,
  rootDomains: r.referringMainDomains ?? 0, spamScore: r.spamScore ?? null, brokenBacklinks: r.brokenBacklinks ?? 0,
  topLinkCountries: top(r.topLinkCountries),
} }));
